from scipy.special import ellipk, ellipe
def loop_Bz(a, I, z, rho):  # exact, vectorised (see physics-01)
    s2=(a+rho)**2+z**2; d2=(a-rho)**2+z**2; m=np.clip(4*a*rho/s2,0,1-1e-15)
    return 4e-7*np.pi*I/(2*np.pi*np.sqrt(s2))*(ellipk(m)+(a*a-rho*rho-z*z)/d2*ellipe(m))

def compute_field_ripple(R, NI, r_roi, coils_z=(0.0,), n=41, kind='pp'):
    """Ripple over a sphere of radius r_roi for coaxial loops at axial positions coils_z."""
    zz, rr = np.meshgrid(np.linspace(-r_roi, r_roi, n), np.linspace(0, r_roi, n), indexing='ij')
    mask = zz**2 + rr**2 <= r_roi**2
    Bz = sum(loop_Bz(R, NI, zz - zc, rr) for zc in coils_z)[mask]
    if kind == 'pp':
        return (Bz.max() - Bz.min()) / sum(loop_Bz(R, NI, -zc, 0.0) for zc in coils_z)
    w = rr[mask] + 1e-12  # volume weight ~ rho for axisymmetric average
    mu = np.average(Bz, weights=w)
    return np.sqrt(np.average((Bz-mu)**2, weights=w)) / mu

from scipy.optimize import brentq
from hts.materials import jc_vs_tb
def current_sharing_temperature(I_op, B_peak, A_sc, Tc=90.0, **jc_kw):
    f = lambda T: jc_vs_tb(T=T, B=B_peak, Tc=Tc, **jc_kw)*A_sc - I_op
    if f(1.0) < 0:
        return None  # not superconducting at this (B, I) even at 1 K
    return brentq(f, 1.0, Tc - 1e-6)

